     }
+
+    /// Removes the regular files directly inside `index-v1/commits` and
+    /// `index-v1/trees` that were last modified more than `RETENTION` before
+    /// `now`, except the files in `keep`. Symlinks and directories are left
+    /// alone and every failure is ignored.
+    pub fn prune(&self, keep: &[&Path], now: SystemTime) {
+        for kind in ["commits", "trees"] {
+            let Ok(entries) = fs::read_dir(self.dir.join("index-v1").join(kind)) else {
+                continue;
+            };
+            for entry in entries.flatten() {
+                let path = entry.path();
+                if keep.contains(&path.as_path()) {
+                    continue;
+                }
+                let Ok(meta) = fs::symlink_metadata(&path) else {
+                    continue;
+                };
+                let old = meta
+                    .modified()
+                    .ok()
+                    .and_then(|modified| now.duration_since(modified).ok())
+                    .is_some_and(|age| age > RETENTION);
+                if meta.file_type().is_file() && old {
+                    let _ = fs::remove_file(&path);
+                }
+            }
+        }
+    }
 }

